  summaryCard: { flex: 1, minWidth: 140, padding: 15, borderRadius: 15, backgroundColor: '#fff', borderWidth: 1, borderColor: '#dbe6ee' },
  summaryValue: { color: '#0077CC', fontSize: 22, fontWeight: 'bold' },
