otesInput]} /><View style={styles.modalActions}><TouchableOpacity style={styles.cancelButton} onPress={() => setServiceModal(false)}><Text style={styles.cancelText}>Cancel</Text></TouchableOpacity><TouchableOpacity disabled={savingService} style={[styles.primaryButton, savingService && styles.disabledButton]} onPress={saveService}><Text style={styles.primaryButtonText}>{savingService ? 'Saving…' : 'Save record'}</Text></TouchableOpacity></View></ScrollView></View></View></Modal>
