          <Text style={styles.fieldLabel}>Condition</Text><View style={styles.modalChipRow}>{CONDITIONS.map((value) => <TouchableOpacity accessibilityRole="radio" accessibilityState={{ checked: form.condition === value }} key={value} onPress={() => setForm((current) => ({ ...current, condition: value }))} style={[styles.modalChip, form.condition === value && styles.modalChipActive]}><Text style={[styles.modalChipText, form.condition === value && styles.modalChipTextActive]}>{CONDITION_LABELS[value]}</Text></TouchableOpacity>)}</View>
