t accessibilityLabel="Service notes" value={serviceForm.notes} onChangeText={(value) => setServiceForm((current) => ({ ...current, notes: value }))} multiline placeholder="What was checked?" style={[styles.input, styles.notesInput]} />{serviceError ? <Text accessibilityRole="alert" style={styles.inlineError}>{serviceError}</Text> : null}<View style={styles.modalActions}><TouchableOpacity accessibilityRole="button" style={styles.cancelButton} onPress={() => setServiceModal(false)}><Text style={styles.cancelText}>Cancel</Text></TouchableOpacity><TouchableOpacity accessibilityRole="button" disabled={savingService} style={[styles.primaryButton, savingService && styles.disabledButton]} onPress={saveService}><Text style={styles.primaryButtonText}>{savingService ? 'Saving…' : 'Save record'}</Text></TouchableOpacity></View></ScrollView></View></View></Modal>
