"],["src/screens/EquipmentDetailScreen.tsx","import React, { useCallback, useMemo, useState } from 'react';
import { ActivityIndicator, Modal, Platform, ScrollView, StyleSheet, Text, TextInput, TouchableOpacity, View } from 'react-native';
import { useFocusEffect } from '@react-navigation/native';
import API from '../api/api';
import EquipmentForm, { isValidEquipmentDate } from '../components/EquipmentForm';
import { getEquipmentStatus } from '../utils/equipment';
import { DiveTrip, Equipment, EquipmentPacking, EquipmentServiceRecord, PlannedDive } from '../types';

type Tab = 'overview' | 'maintenance' | 'packing';
type PackContext = { key: string; kind: 'trip' | 'planned'; id: number; label: string; detail: string };
type ServiceForm = { serviceDate: string; nextDueDate: string; serviceType: string; provider: string; cost: string; notes: string };

const EMPTY_SERVICE: ServiceForm = { serviceDate: '', nextDueDate: '', serviceType: 'Annual inspection', provider: '', cost: '', notes: '' };
const formatDate = (value?: string | null) => {
  if (!value) return 'Not specified';
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? value : date.toLocaleDateString();
};

export default function EquipmentDetailScreen({ route, navigation }: any) {
  const equipmentId = Number(route?.params?.equipmentId);
  const [equipment, setEquipment] = useState<Equipment | null>(null);
  const [records, setRecords] = useState<EquipmentServiceRecord[]>([]);
  const [packs, setPacks] = useState<EquipmentPacking[]>([]);
  const [planned, setPlanned] = useState<PlannedDive[]>([]);
  const [trips, setTrips] = useState<DiveTrip[]>([]);
  const [tab, setTab] = useState<Tab>('overview');
  const [contextKey, setContextKey] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [editVisible, setEditVisible] = useState(false);
  const [serviceError, setServiceError] = useState('');
  const [serviceModal, setServiceModal] = useState(false);
  const [serviceForm, setServiceForm] = useState<ServiceForm>(EMPTY_SERVICE);
  const [savingService, setSavingService] = useState(false);

  const loadDetail = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const [equipmentResponse, recordsResponse, packingResponse, plannedResponse, tripsResponse] = await Promise.all([
        API.get<Equipment>(`/equipment/${equipmentId}`),
        API.get<EquipmentServiceRecord[]>(`/equipment/${equipmentId}/service-records`),
        API.get<EquipmentPacking[]>(`/equipment/packing?equipmentId=${equipmentId}`),
        API.get<PlannedDive[]>('/planned-dives'),
        API.get<DiveTrip[]>('/dive-trips'),
      ]);
      setEquipment(equipmentResponse.data);
      setRecords(Array.isArray(recordsResponse.data) ? recordsResponse.data : []);
      setPacks(Array.isArray(packingResponse.data) ? packingResponse.data : []);
      setPlanned(Array.isArray(plannedResponse.data) ? plannedResponse.data : []);
      setTrips(Array.isArray(tripsResponse.data) ? tripsResponse.data : []);
    } catch {
      setError('We could not load this equipment.');
    } finally {
      setLoading(false);
    }
  }, [equipmentId]);

  useFocusEffect(useCallback(() => { loadDetail(); }, [loadDetail]));

  const contexts = useMemo<PackContext[]>(() => [
    ...trips.map((trip) => ({ key: `trip-${trip.id}`, kind: 'trip' as const, id: trip.id, label: trip.name, detail: `${trip.destination} · ${formatDate(trip.startDate)}` })),
    ...planned.filter((plan) => plan.status === 'upcoming').map((plan) => ({ key: `planned-${plan.id}`, kind: 'planned' as const, id: plan.id, label: plan.location, detail: `${plan.country} · ${formatDate(plan.date)}` })),
  ], [planned, trips]);

  const selectedContext = contexts.find((context) => context.key === contextKey) || contexts[0];
  const selectedPack = selectedContext ? packs.find((pack) => selectedContext.kind === 'trip' ? pack.tripId === selectedContext.id : pack.plannedDiveId === selectedContext.id) : undefined;

  const openServiceForm = () => {
    setServiceError('');
    setServiceForm({ ...EMPTY_SERVICE, serviceDate: new Date().toISOString().slice(0, 10) });
    setServiceModal(true);
  };

  const saveService = async () => {
    if (savingService) return;
    if (!isValidEquipmentDate(serviceForm.serviceDate) || (serviceForm.nextDueDate && !isValidEquipmentDate(serviceForm.nextDueDate)) || !serviceForm.serviceType.trim()) {
      setServiceError('Enter a service type and valid dates as YYYY-MM-DD.');
      return;
    }
    if (serviceForm.cost.trim() && (!Number.isFinite(Number(serviceForm.cost)) || Number(serviceForm.cost) < 0)) {
      setServiceError('Enter a valid non-negative cost.');
      return;
    }
    setServiceError('');
    setSavingService(true);
    try {
      await API.post(`/equipment/${equipmentId}/service-records`, { serviceDate: serviceForm.serviceDate, nextDueDate: serviceForm.nextDueDate || undefined, serviceType: serviceForm.serviceType.trim(), provider: serviceForm.provider.trim() || undefined, cost: serviceForm.cost ? Number(serviceForm.cost) : undefined, notes: serviceForm.notes.trim() || undefined });
      setServiceModal(false);
      await loadDetail();
    } catch {
      setServiceError('Could not save the service record. Please try again.');
    } finally {
      setSavingService(false);
    }
  };

  const removeRecord = async (record: EquipmentServiceRecord) => {
    if (Platform.OS === 'web' && typeof window !== 'undefined' && !window.confirm('Remove this service record?')) return;
    try {
      await API.delete(`/equipment/service-records/${record.id}`);
      setRecords((current) => current.filter((candidate) => candidate.id !== record.id));
    } catch {
      setError('Could not remove the service record.');
    }
  };

  const addPackContext = async (context: PackContext) => {
    try {
      const payload = context.kind === 'trip' ? { equipmentId, tripId: context.id } : { equipmentId, plannedDiveId: context.id };
      const response = await API.post<EquipmentPacking>('/equipment/packing', payload);
      setPacks((current) => current.some((item) => item.id === response.data.id) ? current : [...current, response.data]);
      setContextKey(context.key);
    } catch {
      setError('Could not add this packing context.');
    }
  };

  const togglePack = async () => {
    if (!selectedContext) return;
    if (!selectedPack) {
      await addPackContext(selectedContext);
      return;
    }
    try {
      const response = await API.patch<EquipmentPacking>(`/equipment/packing/${selectedPack.id}`, { packed: !selectedPack.packed });
      setPacks((current) => current.map((item) => item.id === response.data.id ? response.data : item));
    } catch {
      setError('Could not update the packing status.');
    }
  };

  if (loading) return <View style={styles.center}><ActivityIndicator accessibilityLabel="Loading equipment details" color="#0077CC" /></View>;
  if (error && !equipment) return <View style={styles.center}><Text accessibilityRole="alert" style={styles.errorText}>{error}</Text><TouchableOpacity accessibilityRole="button" style={styles.retryButton} onPress={loadDetail}><Text style={styles.retryText}>Retry</Text></TouchableOpacity></View>;
  if (!equipment) return null;

  return (
    <View style={styles.screen}>
      <ScrollView contentContainerStyle={styles.content}>
        <View style={styles.header}><TouchableOpacity accessibilityRole="button" accessibilityLabel="Back to equipment" onPress={() => navigation.goBack()}><Text style={styles.backText}>‹ Equipment</Text></TouchableOpacity><TouchableOpacity accessibilityRole="button" style={styles.editButton} onPress={() => setEditVisible(true)}><Text style={styles.editText}>Edit item</Text></TouchableOpacity></View>
        <View style={styles.hero}><View style={styles.heroCopy}><Text style={styles.eyebrow}>{equipment.category}</Text><Text style={styles.title}>{equipment.name}</Text><Text style={styles.subtitle}>{[equipment.brand, equipment.model].filter(Boolean).join(' ') || 'Brand and model not specified'}</Text></View><View style={styles.statusBadge}><Text style={styles.statusText}>{getEquipmentStatus(equipment) === 'service_due' ? 'Service due' : equipment.condition === 'retired' ? 'Retired' : 'Ready'}</Text></View></View>
        {error ? <Text accessibilityRole="alert" style={styles.inlineError}>{error}</Text> : null}
        <View style={styles.tabs}>{(['overview', 'maintenance', 'packing'] as Tab[]).map((value) => <TouchableOpacity accessibilityRole="button" accessibilityState={{ selected: tab === value }} key={value} onPress={() => setTab(value)} style={[styles.tab, tab === value && styles.tabActive]}><Text style={[styles.tabText, tab === value && styles.tabTextActive]}>{value === 'overview' ? 'Overview' : value === 'maintenance' ? 'Maintenance' : 'Packing list'}</Text></TouchableOpacity>)}</View>

        {tab === 'overview' ? <View style={styles.panel}><View style={styles.infoGrid}><View style={styles.infoCell}><Text style={styles.infoLabel}>Next service</Text><Text style={styles.infoValue}>{formatDate(equipment.nextServiceDate)}</Text></View><View style={styles.infoCell}><Text style={styles.infoLabel}>Serial number</Text><Text style={styles.infoValue}>{equipment.serialNumber || 'Not specified'}</Text></View><View style={styles.infoCell}><Text style={styles.infoLabel}>Purchased</Text><Text style={styles.infoValue}>{formatDate(equipment.purchaseDate)}</Text></View></View><Text style={styles.panelTitle}>Notes</Text><Text style={styles.notes}>{equipment.notes || 'No notes for this item.'}</Text><View style={styles.usageCard}><Text style={styles.panelTitle}>Packing contexts</Text><Text style={styles.notes}>{packs.length ? `${packs.length} trip or dive context${packs.length === 1 ? '' : 's'} linked.` : 'This item has not been added to a packing list yet.'}</Text><TouchableOpacity accessibilityRole="button" style={styles.secondaryButton} onPress={() => setTab('packing')}><Text style={styles.secondaryButtonText}>Manage packing</Text></TouchableOpacity></View></View> : null}

        {tab === 'maintenance' ? <View style={styles.panel}><View style={styles.panelHeader}><Text style={styles.panelTitle}>Service history</Text><TouchableOpacity accessibilityRole="button" style={styles.primaryButton} onPress={openServiceForm}><Text style={styles.primaryButtonText}>+ Add service</Text></TouchableOpacity></View>{records.length ? records.map((record) => <View key={record.id} style={styles.recordCard}><View style={styles.recordHeader}><Text style={styles.recordType}>{record.serviceType}</Text><Text style={styles.recordDate}>{formatDate(record.serviceDate)}</Text></View><Text style={styles.recordMeta}>{record.provider || 'No provider'}{record.cost !== null && record.cost !== undefined ? ` · €${record.cost}` : ''}</Text><Text style={styles.recordNotes}>{record.notes || 'No notes added.'}</Text><View style={styles.recordFooter}><Text style={styles.nextDue}>Next due: {formatDate(record.nextDueDate)}</Text><TouchableOpacity accessibilityRole="button" accessibilityLabel={`Remove ${record.serviceType} record`} onPress={() => removeRecord(record)}><Text style={styles.deleteText}>Remove</Text></TouchableOpacity></View></View>) : <View style={styles.emptyCard}><Text style={styles.emptyTitle}>No service history yet</Text><Text style={styles.emptyText}>Record inspections and repairs to keep your kit safe.</Text><TouchableOpacity accessibilityRole="button" style={styles.secondaryButton} onPress={openServiceForm}><Text style={styles.secondaryButtonText}>Add first record</Text></TouchableOpacity></View>}</View> : null}

